import java.util.*;

class Solution {
  public long countPalindromePaths(List<Integer> parent, String s) {
    int n = parent.size();
    int[] mask = new int[n];
    ArrayList<Integer>[] children = new ArrayList[n];
    for (int i = 0; i < n; i++) children[i] = new ArrayList<>();
    for (int i = 1; i < n; i++) children[parent.get(i)].add(i);
    int[] stack = new int[n];
    int top = 0;
    stack[top++] = 0;
    while (top > 0) {
      int u = stack[--top];
      for (int v : children[u]) {
        mask[v] = mask[u] ^ (1 << (s.charAt(v) - 'a'));
        stack[top++] = v;
      }
    }
    Map<Integer, Long> freq = new HashMap<>();
    long ans = 0;
    for (int x : mask) {
      ans += freq.getOrDefault(x, 0L);
      for (int b = 0; b < 26; b++) ans += freq.getOrDefault(x ^ (1 << b), 0L);
      freq.put(x, freq.getOrDefault(x, 0L) + 1);
    }
    return ans;
  }
}
